// Declaração das folhas de estilo importadas por efeito colateral
// (ex.: `import './globals.css'` e `import '@puckeditor/core/puck.css'`).
// O TypeScript 6 ativa `noUncheckedSideEffectImports` por padrão e exige que
// todo import de efeito colateral resolva para um módulo declarado; o CSS é
// processado pelo bundler do Next.js, não pelo TypeScript.
declare module '*.css';
